// Grass blade "cross-card" cutout textures for Land3DView's instanced grass
// clumps. Unlike the rest of this plugin's 3D rendering (see Land3DView's
// file header on the terrain shader's "no external asset" rule), these are a
// second deliberate exception: real photographed/rendered blade silhouettes
// read as far more convincingly organic up close than anything a few noise
// octaves can fake, which is the whole point of the close-up "zoom into a
// plains cell and see actual grass" view. Sourced from Kenney's "Foliage
// Sprites" pack (kenney.nl/assets/foliage-sprites), CC0 1.0 — no attribution
// required, but see License.txt in that pack. Grayscale/alpha only (tinting
// is done in the grass shader) so they compress small even embedded as
// base64 rather than shipped as separate files.
export const GRASS_BLADE_TEXTURES: readonly string[] = [
	// BLADE_CLUMP_1 (sprite_0052.png)
	"data:image/png;base64,",
	// BLADE_CLUMP_2 (sprite_0061.png)
	"data:image/png;base64,",
	// BLADE_CLUMP_3 (sprite_0063.png)
	"data:image/png;base64,",
];
